import { z } from 'zod';

/** Ids are generated by the client and used as Firestore document ids. */
export const idSchema = z.string().regex(/^[A-Za-z0-9_-]{1,64}$/, 'must be 1–64 letters, digits, - or _');
export const dateSchema = z.iso.date(); // yyyy-mm-dd
const isoDateTime = z.iso.datetime({ offset: true });

export const effortSchema = z.enum(['easy', 'ideal', 'max']);
export const unitSchema = z.enum(['lb', 'kg']);

// ---------------------------------------------------------------- workouts

export const setEntrySchema = z.object({
  id: idSchema,
  setNumber: z.int().min(1).max(100),
  weightKg: z.number().min(0).max(1000).nullable(),
  reps: z.int().min(0).max(1000).nullable(),
  effort: effortSchema.nullable(),
  completed: z.boolean(),
  completedAt: isoDateTime.nullable(),
});

export const sessionExerciseSchema = z.object({
  id: idSchema,
  exerciseId: idSchema,
  groupId: idSchema,
  notes: z.string().max(2000),
  sets: z.array(setEntrySchema).max(50),
});

export const sessionSchema = z.object({
  id: idSchema,
  routineId: idSchema.nullable(),
  name: z.string().trim().min(1).max(100),
  startedAt: isoDateTime,
  endedAt: isoDateTime.nullable(),
  status: z.enum(['active', 'completed']),
  groups: z.array(z.object({ id: idSchema, restSeconds: z.int().min(0).max(3600) })).max(30),
  exercises: z.array(sessionExerciseSchema).max(40),
});
export type SessionDto = z.infer<typeof sessionSchema>;

export const routineSchema = z.object({
  id: idSchema,
  name: z.string().trim().min(1).max(100),
  focus: z.string().max(200),
  estimatedMinutes: z.int().min(1).max(600),
  blocks: z
    .array(
      z.object({
        restSeconds: z.int().min(0).max(3600),
        exercises: z.array(z.object({ exerciseId: idSchema, sets: z.int().min(1).max(20) })).min(1).max(8),
      }),
    )
    .min(1)
    .max(30),
});
export type RoutineDto = z.infer<typeof routineSchema>;

// ---------------------------------------------------------------- profile

export const profilePatchSchema = z
  .object({
    name: z.string().trim().min(1).max(60),
    unit: unitSchema,
    stepGoal: z.int().min(100).max(100_000),
  })
  .partial()
  .strict();
export type ProfilePatchDto = z.infer<typeof profilePatchSchema>;

export const weekPlanSchema = z.object({ week: z.array(idSchema.nullable()).length(7) });

export const goalSchema = z.object({
  type: z.enum(['lose-fat', 'maintain', 'build-muscle']),
  pace: z.enum(['slow', 'moderate', 'fast']),
  weeklyRateKg: z.number().min(-2).max(2),
  startDate: dateSchema,
  startingWeightKg: z.number().min(20).max(400),
  dailyCalories: z.int().min(800).max(10_000),
});

export const lessonsSchema = z.object({ completed: z.array(idSchema).max(500) });

export const demoDataSchema = z.object({
  /** The user's local date, so seeded days line up with their calendar. */
  today: dateSchema,
});

// ---------------------------------------------------------------- tracking

export const bodyWeightSchema = z.object({ weightKg: z.number().min(20).max(400) });

export const foodSchema = z.object({
  date: dateSchema,
  meal: z.enum(['Breakfast', 'Lunch', 'Dinner', 'Snacks']),
  name: z.string().trim().min(1).max(120),
  calories: z.int().min(0).max(10_000),
  proteinG: z.int().min(0).max(1000),
});
export type FoodDto = z.infer<typeof foodSchema>;

const feeling = z.int().min(1).max(5);
export const checkInSchema = z.object({ hunger: feeling, energy: feeling, onPlan: z.boolean() });

export const stepsSchema = z.object({ steps: z.int().min(0).max(200_000) });

export const photoSchema = z.object({
  date: dateSchema,
  /** A downscaled JPEG/PNG as a data URL; kept well under Firestore's 1 MiB document limit. */
  dataUrl: z
    .string()
    .max(700_000)
    .regex(/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/, 'must be a base64 image data URL'),
});

export const sinceQuerySchema = z.object({ since: dateSchema.optional() });
